  ($pfc$coaching$pfc$, $pfc$Coaching Panel$pfc$, $pfc${"eyebrow":"Who's Coaching You","title":"Coaches who've sat where you're sitting","sub":"Every coach on the panel played competitively before they started scoring drills — so the feedback reads like scouting notes, not a generic report card.","photo":"https://images.unsplash.com/photo-1517927033932-b3d18e61fb3a?auto=format&fit=crop&w=900&h=700&q=80","badgeNumber":"6+","badgeText":"Years avg. coaching experience","bullets":["Former state and academy-level footballers","Trained, certified coaching staff with monthly calibration","Direct scouting relationships with partner academies"],"ctaLabel":"See the Career Pathway","ctaHref":"#career"}$pfc$::jsonb, 6),
  ($pfc$training$pfc$, $pfc$Training Section$pfc$, $pfc${"eyebrow":"02 — Training","title":"A pitch isn't required. **Repetition is.**","sub":"Live and recorded sessions built for a driveway, a terrace or a 4×4m room — position-specific, ball-mastery first, scaled to your current level.","positions":[{"index":"01","title":"Striker","text":"Finishing under pressure, first-touch in tight space, movement off the last defender.","space":"4×4m","sessions":"4 / wk"},{"index":"02","title":"Winger","text":"1v1 explosiveness, crossing accuracy, change-of-direction speed.","space":"5×5m","sessions":"4 / wk"},{"index":"03","title":"Attacking Mid","text":"Vision drills, weighted passing, receiving on the half-turn.","space":"4×4m","sessions":"3 / wk"},{"index":"04","title":"Center-Back","text":"Aerial duels, jockeying footwork, playing the ball out from the back.","space":"4×4m","sessions":"3 / wk"},{"index":"05","title":"Full-Back","text":"Overlap timing, recovery sprints, delivery under fatigue.","space":"6×4m","sessions":"4 / wk"},{"index":"06","title":"Goalkeeper","text":"Shot-stopping reflexes, distribution, one-on-one composure.","space":"4×3m","sessions":"5 / wk"}],"note":"Every drill is filmed by you on a phone and reviewed by a coach within 48 hours — no equipment beyond a ball and cones required."}$pfc$::jsonb, 7),
  ($pfc$career$pfc$, $pfc$Career Pathway$pfc$, $pfc${"eyebrow":"03 — Career Pathway","title":"From backyard drills to a **trial-ready file**","sub":"A fixed sequence, followed by every athlete on the programme — because a career doesn't start with a trial, it starts with an honest assessment.","steps":[{"num":"01 /05","title":"Assessment Call","text":"A 30-minute video call with a coach to benchmark your current level, position and goals."},{"num":"02 /05","title":"Personalised Roadmap","text":"A 12-week plan covering training, fitness and the trials you're realistically ready for."},{"num":"03 /05","title":"Trial Preparation","text":"Mock evaluations scored exactly the way our scouting panel scores real trials."},{"num":"04 /05","title":"Scouting Introduction","text":"Your tracked athlete profile is shared with partner academies matching your age and position."},{"num":"05 /05","title":"Contract & Move Guidance","text":"Support reading offers, planning relocation and managing the transition — for you and your family."}]}$pfc$::jsonb, 8),
  ($pfc$nutrition$pfc$, $pfc$Fitness & Nutrition$pfc$, $pfc${"eyebrow":"04 — Fitness & Nutrition","title":"Match-fit, **not just gym-fit**","sub":"Weight and nutrition plans built around match demands, not generic diet templates. Cut for pace, build for duels, or fuel for ninety minutes without crashing.","cards":[{"title":"Lean For Pace","text":"Structured cut for players carrying extra weight into pre-season, without losing sprint power.","carbs":50,"protein":30,"fat":20},{"title":"Build For Duels","text":"Controlled surplus for players who lose the physical battle, paired with progressive strength work.","carbs":45,"protein":35,"fat":20},{"title":"Match-Day Fuelling","text":"Carb and hydration timing around kickoff, so your legs are still yours in minute eighty.","carbs":60,"protein":20,"fat":20}],"include":"Every track includes a 1:1 monthly check-in with a sports nutritionist and a weekly weigh-in log reviewed by your coach."}$pfc$::jsonb, 9),
  ($pfc$tracking$pfc$, $pfc$Performance Tracking$pfc$, $pfc${"eyebrow":"05 — Performance Tracking","title":"Every session becomes **a data point**","sub":"Five metrics, one number that moves: Speed, Stamina, Technique, Strength and Agility — scored from your submitted drills and updated after every review.","photo":"https://images.unsplash.com/photo-1574629810360-7efbbe195018?auto=format&fit=crop&w=800&h=680&q=80","metricsTitle":"Five metrics, one profile","metricsCaption":"Current form, scored out of 100 after this week's review","metrics":[{"label":"Speed","value":82},{"label":"Stamina","value":88},{"label":"Technique","value":76},{"label":"Strength","value":71},{"label":"Agility","value":79}],"metricsFootnote":"Up from an average baseline of 45 in Week 1","methodTitle":"Tracking Method","methodCaption":"How a drill becomes a metric","methodSteps":[{"icon":"upload","title":"Submit Drill Video","text":"Film the weekly drill set on your phone and upload it from the app."},{"icon":"check","title":"Coach Scores It","text":"A coaching panel member scores technique, effort and outcome within 48 hours."},{"icon":"refresh","title":"Metrics Update","text":"Your Speed, Stamina, Technique, Strength and Agility scores shift on the radar."},{"icon":"chat","title":"Monthly Report Call","text":"A 15-minute call walks through your trend line and adjusts the roadmap."}]}$pfc$::jsonb, 10),
  ($pfc$plans$pfc$, $pfc$Membership Section$pfc$, $pfc${"eyebrow":"06 — Membership","title":"Pick a training load **you can sustain**","sub":"One subscription covers coaching, tracking and trial access. Upgrade or downgrade anytime.","monthlyLabel":"Monthly","annualLabel":"Annual","annualSave":"2 mo free","footnote":"Prices in INR, inclusive of coaching platform access. Cancel anytime. GST invoice provided at checkout."}$pfc$::jsonb, 11),
  ($pfc$videos$pfc$, $pfc$Video Library Section$pfc$, $pfc${"eyebrow":"07 — Session Library","title":"Drill it again until **it's automatic**","sub":"Every live session is recorded. Rewatch technique breakdowns, match analysis and recovery routines whenever you need them."}$pfc$::jsonb, 12),
  ($pfc$checkout$pfc$, $pfc$Checkout & Trust$pfc$, $pfc${"eyebrow":"08 — Checkout","title":"Secure checkout, **built for India**","methods":[{"icon":"card","label":"UPI"},{"icon":"card-dot","label":"Credit & Debit Cards"},{"icon":"bank","label":"Net Banking"},{"icon":"wallet","label":"Wallets"}],"trust":[{"icon":"lock","text":"256-bit encrypted checkout"},{"icon":"x","text":"Cancel anytime, no lock-in"},{"icon":"file","text":"GST invoice on every payment"},{"icon":"chat","text":"Support in English & Hindi"}]}$pfc$::jsonb, 13),
  ($pfc$testimonials$pfc$, $pfc$Testimonials$pfc$, $pfc${"eyebrow":"Players On The Pathway","title":"Numbers convince coaches. **Stories convince us.**","items":[{"quote":"Two Open Trials in six months. The mock evaluations were harder than the real thing, so walking onto the pitch in Bengaluru felt normal instead of terrifying.","name":"Arjun","meta":"16 · Pune"},{"quote":"My weigh-ins used to be a guessing game. Now there's a plan for match days and a coach who actually looks at the numbers with me every month.","name":"Meher","meta":"15 · Kochi"},{"quote":"The roadmap told me I wasn't ready for a trial yet — and it was right. Twelve weeks later, my radar chart backed up what my legs already knew.","name":"Devraj","meta":"19 · Ranchi"}]}$pfc$::jsonb, 14),
  ($pfc$finalCta$pfc$, $pfc$Final CTA$pfc$, $pfc${"eyebrow":"Start Here","title":"Your first trial rejection shouldn't be the last time anyone saw you play","paragraph":"Book a free 20-minute assessment call. We'll tell you honestly where you stand and what a realistic 12-week plan looks like.","ctaLabel":"Book Your Free Assessment","ctaHref":"#plans"}$pfc$::jsonb, 15),
  ($pfc$footer$pfc$, $pfc$Footer$pfc$, $pfc${"about":"Football-only coaching consultancy. Pan-India trials, online training and a tracked pathway to the professional game.","newsletterPlaceholder":"Get new trial cities in your inbox","newsletterButton":"Notify Me","columns":[{"heading":"Programs","links":[{"label":"Trials","href":"#trials"},{"label":"Home Training","href":"#training"},{"label":"Career Pathway","href":"#career"},{"label":"Nutrition","href":"#nutrition"},{"label":"Performance Tracking","href":"#tracking"},{"label":"Video Library","href":"#videos"}]},{"heading":"Company","links":[{"label":"About Proforma Co","href":"#"},{"label":"Coaching Panel","href":"#"},{"label":"Partner Academies","href":"#"},{"label":"Careers","href":"#"}]},{"heading":"Support","links":[{"label":"Help Center","href":"#"},{"label":"Contact a Coach","href":"#"},{"label":"WhatsApp Support","href":"#"},{"label":"FAQ","href":"#"}]},{"heading":"Legal","links":[{"label":"Terms of Service","href":"#"},{"label":"Privacy Policy","href":"#"},{"label":"Refund Policy","href":"#"},{"label":"GST Invoice","href":"#"}]}],"social":[{"icon":"instagram","href":"#","label":"Instagram"},{"icon":"youtube","href":"#","label":"YouTube"},{"icon":"whatsapp","href":"#","label":"WhatsApp"}],"copyright":"Proforma Co Sports Consultancy. All rights reserved.","legal":"Football-only coaching consultancy · Operating pan-India · Not affiliated with any national federation."}$pfc$::jsonb, 16),
  ($pfc$seo$pfc$, $pfc$SEO / Meta$pfc$, $pfc${"title":"Proforma Co — Football Coaching Consultancy | Pan-India Trials & Online Training","description":"Proforma Co is a football-only coaching consultancy: pan-India trial placement, online home training, career guidance, nutrition consultancy and tracked performance — all in one subscription."}$pfc$::jsonb, 17)
