  ('admin',  $pfc$admin$pfc$,      crypt($pfc$Proforma@2026$pfc$, gen_salt('bf', 10)),   $pfc$Proforma Admin$pfc$, null, false),
  ('tutor',  $pfc$COACH-DEMO$pfc$, crypt($pfc$Coach@2026$pfc$, gen_salt('bf', 10)),   $pfc$Rahul Menon$pfc$,    $pfc$919000000001$pfc$, false),
  ('client', $pfc$PFC-DEMO$pfc$,   crypt($pfc$Athlete@2026$pfc$, gen_salt('bf', 10)), $pfc$Arjun Nair$pfc$,     $pfc$919000000002$pfc$, false)
