select u.id, $pfc$Arjun Nair$pfc$, 16, $pfc$Striker$pfc$, $pfc$Pune$pfc$, $pfc$Maharashtra$pfc$,
       $pfc$919000000002$pfc$, $pfc$Sunita Nair$pfc$, $pfc$919000000003$pfc$, 172.0, 61.5,
       $pfc$Trial-ready for U-17 academy intake$pfc$,
       (select id from tutors limit 1),
       (select id from plans where slug = $pfc$pro$pfc$),
